import { expect, expectStatus, test } from "../../fixtures";

test("A vendor from another tenant is invisible", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const otherTenantVendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act
  const response = await member.get(`/api/vendors/${otherTenantVendor.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
